void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Adjust aspect ratio
    float aspect = iResolution.x/iResolution.y;
    vec2 adjustedUV = vec2(uv.x * aspect - aspect*0.5, uv.y - 0.5);

    // Create movement
    float movement = 0.25 * sin(iTime);

    // Calculate distance fields for two metaballs
    float d1 = length(adjustedUV - vec2(movement, 0.0));
    float d2 = length(adjustedUV + vec2(movement, 0.0));

    // Calculate metaball effect
    float metaball = 1.0/(d1*20.0) + 1.0/(d2*20.0);
    metaball = metaball * 0.8;

    // Apply smoothstep for clean edges
    float final = smoothstep(0.5, 0.51, metaball);

    // Output final color
    fragColor = vec4(final, final, final, 1.0);
}
